void* thread_func(void* arg) {
    long thread_num = (long)arg;
    return (void*)(thread_num * 2);
}

// Thread Creation and Wait
pthread_t t1, t2;
long data1 = 1, data2 = 2;

pthread_create(&t1, NULL, thread_func, (void*)data1);
pthread_create(&t2, NULL, thread_func, (void*)data2);

void* exit_status1;
pthread_join(t1, &exit_status1);
// exit_status1 holds (void*)2

// Detached thread (Resource cleanup automatic)
pthread_attr_t attr;
pthread_attr_init(&attr);
pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
pthread_create(&t1, &attr, thread_func, NULL);
pthread_attr_destroy(&attr);


pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
int shared_resource = 0;

// Mutual Exclusion (Locking)
void access_shared() {
    pthread_mutex_lock(&mtx);

    // Critical Section
    shared_resource++;

    pthread_mutex_unlock(&mtx);
}

void mutex_cleanup() {
    pthread_mutex_destroy(&mtx);
}


pthread_cond_t cond_var;
pthread_mutex_t cond_mtx;
int item_available = 0;

// Condition Variables (Waiting)
void consumer_wait() {
    pthread_mutex_lock(&cond_mtx);
    while (item_available == 0) {
        pthread_cond_wait(&cond_var, &cond_mtx);
    }
    // Resource consumed
    pthread_mutex_unlock(&cond_mtx);
}

// Condition Variables (Signaling)
void producer_signal() {
    pthread_mutex_lock(&cond_mtx);
    item_available = 1;
    pthread_cond_signal(&cond_var); // Wakes one thread
    // pthread_cond_broadcast(&cond_var); // Wakes all threads
    pthread_mutex_unlock(&cond_mtx);
}
